CREATE TABLE IF NOT EXISTS ai_context_bundles(id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,conversation_id VARCHAR(64) NOT NULL,content_hash CHAR(64) NOT NULL,snapshot_cipher MEDIUMTEXT NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL,KEY owner_conversation(user_id,conversation_id),KEY expiry(expires_at),CONSTRAINT context_owner_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ai_provider_consents(user_id BIGINT UNSIGNED PRIMARY KEY,allowed TINYINT(1) NOT NULL,notice_version VARCHAR(64) NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT ai_consent_owner_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ai_stream_leases(id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,KEY owner_expiry(user_id,expires_at),CONSTRAINT ai_stream_owner_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
